<script setup lang="ts">
import { EVENT_TITLE } from '#shared/event-brand'
const { t, eventText } = useAppI18n()
import { Monitor, SlidersHorizontal, LogOut, ArrowUpRight, Check, Trash2, Eye, ShieldCheck, Pause, Play, Radio, Shuffle } from 'lucide-vue-next'
import { defaults, type Settings, type Krathong } from '#shared/models'
import type { SceneLayout } from '#shared/scene-layout'
const {state,connected}=useLive();const logged=ref(false);const password=ref('');const loginError=ref('');const error=ref('');const notice=ref('');const busy=ref(false);const draft=ref<Settings>(structuredClone(defaults));const tab=ref('scene');const items=ref<Krathong[]>([]);const confirmClear=ref(false);const origin=ref('');const saving=ref(false);const checking=ref(true)
const eventTitle=computed({get:()=>eventText(draft.value.title,'title'),set:(value:string)=>{draft.value.title=value}})
const confirmDelete=ref<Krathong>();const deleting=ref(false);const deleteError=ref('')
const randomCount=ref(1);const randomBusy=ref(false);const randomNotice=ref('');const randomError=ref('');let randomIds:string[]=[]
const eventSubtitle=computed({get:()=>eventText(draft.value.subtitle,'subtitle'),set:(value:string)=>{draft.value.subtitle=value}})
const pending=computed(()=>items.value.filter(k=>k.status==='pending'));const guestUrl=computed(()=>draft.value.guestUrl||origin.value)
const sliders=[{key:'lanternScale',label:'ขนาดโคมลอย',hint:'ปรับขนาดโคมลอยทุกดวงบนฉาก',min:.5,max:8,step:.1,unit:'×'},{key:'size',label:'ขนาดกระทง',hint:'ปรับให้เหมาะกับระยะมองและขนาดจอ',min:.4,max:2,step:.05,unit:'×'},{key:'nameScale',label:'ขนาดชื่อใต้กระทง',hint:'ใช้กับชื่อใต้กระทงทุกใบ',min:.5,max:3,step:.05,unit:'×'},{key:'wishScale',label:'ขนาดกล่องคำอวยพร',hint:'ปรับกล่องและข้อความคำอวยพรทุกใบ',min:.5,max:3,step:.05,unit:'×'},{key:'speed',label:'ความเร็วกระทง',hint:'ความเร็วที่กระทงลอยผ่านหน้าจอ',min:.1,max:3,step:.1,unit:'×'},{key:'sceneSpeed',label:'ความเร็วฉากหลัง',hint:'การเคลื่อนตัวของหมอกและเมฆ',min:0,max:3,step:.1,unit:'×'},{key:'waterSpeed',label:'ความเร็วสายน้ำ',hint:'จังหวะระลอกคลื่นบนผิวน้ำ',min:.1,max:3,step:.1,unit:'×'},{key:'brightness',label:'ความสว่างฉาก',hint:'ปรับตามแสงภายในสถานที่',min:.3,max:1.5,step:.05,unit:'×'}] as const
let editRevision=0
let saveTimer:ReturnType<typeof setTimeout>;let refreshTimer:ReturnType<typeof setInterval>;let queued=false;let sceneSaveTimer:ReturnType<typeof setTimeout>|undefined
async function refresh(){const revision=editRevision;try{const r=await $fetch<any>('/api/admin/state');logged.value=true;items.value=r.krathongs;if(revision===editRevision&&!saving.value&&!queued)draft.value={...r.settings}}catch{logged.value=false}finally{checking.value=false}}
onMounted(()=>{origin.value=location.origin;refresh();refreshTimer=setInterval(()=>{if(logged.value)refresh()},5000)})
onBeforeUnmount(()=>{clearTimeout(saveTimer);clearTimeout(sceneSaveTimer);clearInterval(refreshTimer)})
async function login(){busy.value=true;loginError.value='';try{await api('/login',{method:'POST',body:{password:password.value}});password.value='';await refresh()}catch(e:any){loginError.value=e.message}finally{busy.value=false}}
async function logout(){await api('/logout',{method:'POST'});logged.value=false}
function schedule(){editRevision++;queued=true;notice.value='กำลังปรับ…';clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}
function updateScene(value:SceneLayout){editRevision++;draft.value.scene=value;queued=true;notice.value='กำลังปรับ…';if(sceneSaveTimer)return;sceneSaveTimer=setTimeout(()=>{sceneSaveTimer=undefined;clearTimeout(saveTimer);save()},150)}
async function save(){if(saving.value){queued=true;return}queued=false;saving.value=true;error.value='';const snapshot=JSON.stringify(draft.value);try{await api('/admin/settings',{method:'PATCH',body:JSON.parse(snapshot)});notice.value='บันทึกและส่งขึ้นจอแล้ว'}catch(e:any){error.value=e.message;notice.value='ยังไม่บันทึก'}finally{saving.value=false;if(queued||snapshot!==JSON.stringify(draft.value)){clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}}}
async function moderate(id:string,status:string){try{await api(`/admin/krathongs/${id}`,{method:'PATCH',body:{status}});await refresh()}catch(e:any){error.value=e.message}}
async function clear(){if(deleting.value)return;deleting.value=true;deleteError.value='';try{await api('/admin/krathongs',{method:'DELETE'});confirmClear.value=false;await refresh()}catch(e:any){deleteError.value=e.message}finally{deleting.value=false}}
async function removeSelected(){if(deleting.value||!confirmDelete.value)return;deleting.value=true;deleteError.value='';try{await api(`/admin/krathongs/${confirmDelete.value.id}`,{method:'PATCH',body:{status:'deleted'}});confirmDelete.value=undefined;await refresh()}catch(e:any){deleteError.value=e.message}finally{deleting.value=false}}
async function sendRandom(){if(randomBusy.value)return;randomBusy.value=true;randomError.value='';randomNotice.value='';randomIds.length||(randomIds=Array.from({length:randomCount.value},()=>crypto.randomUUID()));try{const r=await api('/admin/krathongs/random',{method:'POST',body:{ids:randomIds}});randomNotice.value=`${r.requested} ${t('กระทงสุ่มส่งขึ้นจอแล้ว')}`;randomIds=[];await refresh()}catch(e:any){randomError.value=e.message}finally{randomBusy.value=false}}
const toggles=[{key:'showNames',label:'แสดงชื่อบนกระทง'},{key:'showWishes',label:'แสดงคำอวยพร'},{key:'accepting',label:'เปิดรับกระทงจากแขก'},{key:'moderation',label:'ตรวจคำอวยพรก่อนขึ้นจอ'}] as const
const displayToggles=[{key:'showQr',label:'แสดง QR บนจองาน'},{key:'showBrand',label:'แสดงโลโก้งานและสถานะ LIVE'},{key:'showHeading',label:'แสดงชื่องานและข้อความต้อนรับ'},{key:'showCount',label:'แสดงจำนวนกระทง'},{key:'showControls',label:'แสดงเมนูควบคุมบนจอ'},{key:'showFooter',label:'แสดงข้อความมุมล่าง'}] as const
function setDisplayUi(visible:boolean){for(const item of displayToggles)draft.value[item.key]=visible;schedule()}
useHead(()=>({title:`${EVENT_TITLE} • ${t('ห้องควบคุมสายน้ำ')}`}))
</script>
<template>
<div class="admin-page"><header class="site-header"><BrandMark/><nav><LanguageSwitch/><span class="header-link"><span class="status-dot" :class="{offline:!connected}"/>{{t(connected?'ระบบพร้อมใช้งาน':'กำลังเชื่อมต่อ')}}</span><button v-if="logged" class="text-button" @click="logout"><LogOut :size="16"/>{{t('ออกจากระบบ')}}</button></nav></header>
<div v-if="checking" class="login-panel"><p>{{t('กำลังตรวจสอบเซสชัน…')}}</p></div>
<form v-else-if="!logged" class="login-panel" @submit.prevent="login"><span class="login-symbol"><ShieldCheck :size="30"/></span><p class="eyebrow">EVENT CONTROL ROOM</p><h1>{{t('เบื้องหลังคืนที่งดงาม')}}</h1><p>{{t('เข้าสู่ระบบเพื่อดูแลสายน้ำของค่ำคืนนี้')}}</p><label for="admin-password">{{t('รหัสผ่านผู้จัดงาน')}}</label><input id="admin-password" v-model="password" type="password" autocomplete="current-password" required :placeholder="t('รหัสผ่านผู้จัดงาน')"/><p v-if="loginError" class="error-message" role="alert">{{t(loginError)}}</p><button class="primary-button" :disabled="busy">{{t(busy?'กำลังเข้าสู่ระบบ…':'เข้าสู่ห้องควบคุม')}}<ArrowUpRight :size="17"/></button><NuxtLink to="/" class="text-button">{{t('กลับไปหน้าสร้างกระทง')}}</NuxtLink></form>
<main v-else class="admin-main"><div class="admin-title"><div><p class="eyebrow">EVENT CONTROL ROOM</p><h1>{{t('ห้องควบคุมสายน้ำ')}}</h1><p>{{t('ปรับบรรยากาศให้พอดีกับค่ำคืน ทุกการเปลี่ยนแปลงส่งตรงขึ้นจอ')}}</p></div><NuxtLink to="/display" target="_blank" class="primary-button"><Monitor :size="17"/>{{t('เปิดจอแสดงงาน')}}<ArrowUpRight :size="16"/></NuxtLink></div>
<div class="admin-stats"><div><Radio :size="19"/><span>{{t('กระทงทั้งหมด')}}<strong>{{state.total}}</strong></span></div><div><ShieldCheck :size="19"/><span>{{t('รอการตรวจสอบ')}}<strong>{{pending.length}}</strong></span></div><div><Monitor :size="19"/><span>{{t('แสดงบนจอ')}}<strong>{{state.krathongs.length}}</strong></span></div><div><span class="status-dot" :class="{offline:!connected}"/><span>{{t('สถานะการแสดงผล')}}<strong class="status-text">{{t(draft.showMemorial?'ภาพถวายอาลัย':draft.paused?'หยุดชั่วคราว':'กำลังล่องลอย')}}</strong></span></div></div>
<div class="admin-boat-tools"><div><Shuffle :size="21"/><div><h2>{{t('สุ่มกระทงตกแต่ง')}}</h2><p>{{t('ส่งกระทงแบบไม่มีชื่อ ธง หรือคำอวยพรขึ้นจอ')}}</p></div></div><div class="random-actions"><label for="random-count">{{t('จำนวน')}}</label><select id="random-count" v-model.number="randomCount" :disabled="randomBusy" @change="randomIds=[]"><option v-for="count in [1,5,10,20]" :key="count" :value="count">{{count}}</option></select><button class="primary-button" :disabled="randomBusy" @click="sendRandom"><Shuffle :size="16"/>{{t(randomBusy?'กำลังส่ง…':'สุ่มและส่งขึ้นจอ')}}</button><a href="#krathong-management" class="outline-button"><Trash2 :size="14"/>{{t('จัดการกระทง')}}</a></div><p v-if="randomNotice" class="random-notice" role="status">{{randomNotice}}</p><p v-if="randomError" class="error-message" role="alert">{{t(randomError)}}</p></div>
<div class="admin-workspace"><section class="admin-preview"><div class="section-bar"><span><Eye :size="16"/>{{t('ภาพตัวอย่างจองาน')}}</span><span class="live-label">LIVE PREVIEW</span></div><SceneLayoutEditor :settings="draft" :krathongs="state.krathongs" @update:scene="updateScene"/><div class="preview-toolbar"><span>{{t('ทุกการจัดวางส่งตรงขึ้นจอ')}}</span><button class="outline-button" @click="draft.paused=!draft.paused;schedule()"><Play v-if="draft.paused" :size="14"/><Pause v-else :size="14"/>{{t(draft.paused?'เล่นต่อ':'พักการเคลื่อนไหว')}}</button></div>
<div class="qr-admin-card"><div class="small-qr"><QrCode v-if="guestUrl" :value="guestUrl" :size="112"/></div><div><p class="eyebrow">INVITE YOUR GUESTS</p><h3>{{t('หนึ่งสแกน เริ่มต้นหนึ่งความหวัง')}}</h3><p>{{t('ใช้ QR เดียวกันได้ทุกโต๊ะในงาน')}}</p><NuxtLink to="/qr" target="_blank" class="text-button gold">{{t('เปิดหน้าพิมพ์ QR')}}<ArrowUpRight :size="15"/></NuxtLink></div></div>
</section>
<section class="control-panel"><div class="section-bar"><span><SlidersHorizontal :size="16"/>{{t('ตั้งค่าการแสดงผล')}}</span><span class="save-state" aria-live="polite">{{t(notice||'ปรับแล้วบันทึกอัตโนมัติ')}}</span></div><div class="memorial-control"><div><label for="show-memorial">{{t('แสดงภาพถวายอาลัยเต็มจอ')}}</label><p id="memorial-hint">{{t('เปิดเพื่อแสดงภาพบนจองานทันที ปิดเพื่อกลับสู่แม่น้ำ')}}</p></div><input id="show-memorial" v-model="draft.showMemorial" class="toggle" type="checkbox" role="switch" aria-describedby="memorial-hint" @change="schedule"/></div><div class="display-ui-settings"><h3>{{t('องค์ประกอบบนจอ Display')}}</h3><p class="field-help">{{t('เปิดปิดแยกกันได้ มีผลบนจอทันที')}}</p><div class="display-ui-actions"><button class="outline-button" @click="setDisplayUi(false)">{{t('ซ่อน UI ทั้งหมด')}}</button><button class="outline-button" @click="setDisplayUi(true)">{{t('แสดง UI ทั้งหมด')}}</button></div><div v-for="toggle in displayToggles" :key="toggle.key" class="toggle-row"><label :for="toggle.key">{{t(toggle.label)}}</label><input :id="toggle.key" v-model="draft[toggle.key]" class="toggle" type="checkbox" role="switch" @change="schedule"/></div></div><div class="control-tabs"><button :class="{active:tab==='scene'}" @click="tab='scene'">{{t('ฉากและการเคลื่อนไหว')}}</button><button :class="{active:tab==='event'}" @click="tab='event'">{{t('ข้อมูลงาน')}}</button></div><div class="control-body"><template v-if="tab==='scene'"><div v-for="slider in sliders" :key="slider.key" class="range-field"><label :for="slider.key">{{t(slider.label)}}<output>{{Number(draft[slider.key]).toFixed(2)}}{{t(slider.unit)}}</output></label><p>{{t(slider.hint)}}</p><input :id="slider.key" v-model.number="draft[slider.key]" type="range" :min="slider.min" :max="slider.max" :step="slider.step" @input="schedule"/></div></template><template v-else><label for="event-title">{{t('ชื่องานบนจอ')}}</label><input id="event-title" v-model="eventTitle" maxlength="80" @input="schedule"/><label for="event-subtitle">{{t('ข้อความต้อนรับ')}}</label><textarea id="event-subtitle" v-model="eventSubtitle" maxlength="140" rows="2" @input="schedule"/><label for="guest-url">{{t('URL สำหรับแขก / QR')}}</label><input id="guest-url" v-model="draft.guestUrl" type="url" :placeholder="origin" @change="schedule"/><p class="field-help">{{t('ใช้ URL ที่มือถือของแขกเข้าถึงได้ เช่น HTTPS domain หรือ IP เครื่องในเครือข่ายงาน')}}</p><div class="toggle-row" v-for="toggle in toggles" :key="toggle.key"><label :for="toggle.key">{{t(toggle.label)}}</label><input :id="toggle.key" v-model="draft[toggle.key]" class="toggle" type="checkbox" @change="schedule"/></div></template><p v-if="error" role="alert" class="error-message">{{t(error)}} <button class="text-button" @click="save">{{t('ลองบันทึกอีกครั้ง')}}</button></p></div></section></div>
<section id="krathong-management" class="moderation-panel"><div class="section-bar"><span><ShieldCheck :size="17"/>{{t('กระทงและคำอธิษฐาน')}}<small>{{items.length}} {{t('รายการทั้งหมด')}}</small></span><button class="text-button danger" @click="confirmClear=true;deleteError='' "><Trash2 :size="15"/>{{t('ลบกระทงทั้งหมด')}}</button></div><div v-if="!items.length" class="empty-list"><span>✧</span>{{t('ค่ำคืนนี้กำลังจะเริ่มต้น กระทงจากแขกจะแสดงที่นี่')}}</div><div v-for="item in items" :key="item.id" class="moderation-row"><KrathongArt :base="item.base" :flower="item.flower" :country="item.country"/><div><strong>{{item.name||t('กระทงสุ่ม')}} <span class="badge" :class="{pending:item.status==='pending'}">{{t(item.status==='pending'?'รอตรวจสอบ':'บนสายน้ำ')}}</span></strong><p>{{item.wish||t(item.source==='admin-random'?'กระทงตกแต่ง ไม่มีชื่อหรือคำอวยพร':'ไม่ได้ระบุคำอวยพร')}}</p></div><div class="row-actions"><button v-if="item.status==='pending'" class="outline-button" @click="moderate(item.id,'approved')"><Check :size="15"/>{{t('อนุมัติ')}}</button><button class="outline-button danger" :aria-label="`${t('ลบกระทง')}: ${item.name||t('กระทงสุ่ม')}`" @click="confirmDelete=item;deleteError=''"><Trash2 :size="15"/>{{t('ลบกระทง')}}</button></div></div></section>
</main>
<div v-if="confirmClear" class="modal-backdrop"><section role="alertdialog" aria-modal="true" aria-labelledby="clear-title" class="confirm-modal"><h2 id="clear-title">{{t('ล้างกระทงทั้งหมด?')}}</h2><p>{{t('กระทงและคำอวยพรทั้งหมดจะถูกลบถาวร และนำออกจากจอทันที การตั้งค่างานยังอยู่')}}</p><p v-if="deleteError" class="error-message" role="alert">{{t(deleteError)}}</p><div><button class="outline-button" :disabled="deleting" @click="confirmClear=false">{{t('ยกเลิก')}}</button><button class="primary-button danger-button" :disabled="deleting" @click="clear">{{t('ยืนยันลบทั้งหมด')}}</button></div></section></div>
<div v-if="confirmDelete" class="modal-backdrop"><section role="alertdialog" aria-modal="true" aria-labelledby="delete-boat-title" class="confirm-modal"><h2 id="delete-boat-title">{{t('ลบกระทงนี้ออกจากจอ?')}}</h2><div class="delete-boat-preview"><KrathongArt :base="confirmDelete.base" :flower="confirmDelete.flower" :country="confirmDelete.country"/><div><strong>{{confirmDelete.name||t('กระทงสุ่ม')}}</strong><p>{{confirmDelete.wish||t('ไม่ได้ระบุคำอวยพร')}}</p></div></div><p>{{t('กระทงที่เลือกจะถูกลบถาวรและนำออกจากจอทันที')}}</p><p v-if="deleteError" class="error-message" role="alert">{{t(deleteError)}}</p><div><button class="outline-button" :disabled="deleting" @click="confirmDelete=undefined">{{t('ยกเลิก')}}</button><button class="primary-button danger-button" :disabled="deleting" @click="removeSelected">{{t('ยืนยันลบกระทง')}}</button></div></section></div>
</div>
</template>

<style scoped>
.display-ui-settings{padding:20px 22px 6px;border-bottom:1px solid var(--line)}.display-ui-settings h3{font-size:14px;color:var(--gold);margin-bottom:6px}.display-ui-actions{display:flex;gap:8px;margin:12px 0 16px}.display-ui-actions button{font-size:11px}
</style>
